from __future__ import annotations

import base64
from pathlib import Path
import zlib

SIXEL_ZLIB_B64 = ""

root = Path(__file__).resolve().parents[2]

sixel = zlib.decompress(base64.b64decode(SIXEL_ZLIB_B64)).decode("utf-8")
(root / "rust/terminal-adapter/src").mkdir(parents=True, exist_ok=True)
(root / "rust/terminal-adapter/src/sixel.rs").write_text(sixel, encoding="utf-8")
(root / "rust/terminal-adapter/src/lib.rs").write_text(
    """//! Safe Rust migration track for Windows Terminal's adapter layer.\n//!\n//! R03 starts with protocol-heavy components that can be isolated from the C++\n//! `TextBuffer`, renderer, and platform integration surfaces.\n\n#![forbid(unsafe_code)]\n\npub mod sixel;\n""",
    encoding="utf-8",
)
(root / "rust/terminal-adapter/Cargo.toml").write_text(
    """[package]\nname = \"terminal-adapter\"\nversion = \"0.0.0\"\npublish = false\nedition.workspace = true\nlicense.workspace = true\nrepository.workspace = true\n\n[dependencies]\nterminal-parser = { path = \"../terminal-parser\" }\n\n[lints]\nworkspace = true\n""",
    encoding="utf-8",
)

cargo = (root / "Cargo.toml").read_text(encoding="utf-8")
needle = 'members = [\n'
if '"rust/terminal-adapter"' not in cargo:
    cargo = cargo.replace(needle, needle + '    "rust/terminal-adapter",\n', 1)
(root / "Cargo.toml").write_text(cargo, encoding="utf-8")

lock = (root / "Cargo.lock").read_text(encoding="utf-8")
if 'name = "terminal-adapter"' not in lock:
    marker = '[[package]]\nname = "terminal-input"'
    block = '[[package]]\nname = "terminal-adapter"\nversion = "0.0.0"\ndependencies = [\n "terminal-parser",\n]\n\n'
    lock = lock.replace(marker, block + marker, 1)
(root / "Cargo.lock").write_text(lock, encoding="utf-8")

(root / "doc/rust-migration/r03-sixel.md").write_text(
    """# R03a — Sixel core\n\nR03 begins the Adapter migration after the R01-R02 semantic-core checkpoint.\nThe first slice ports the deterministic core of `SixelParser` into a new safe,\nplatform-neutral `terminal-adapter` crate.\n\n## In scope\n\n- DEC conformance-level cell sizes and color-table limits.\n- Sixel command grammar (`#`, `!`, `$`, `-`, `+`, `\"`, and sixel data bytes).\n- Parameter accumulation using the parser's `MAX_PARAMETER_VALUE`.\n- Macro and raster aspect-ratio behavior.\n- Transparent/opaque background behavior and raster dimensions.\n- VT340 base palette plus XTerm extended colors.\n- DEC HLS and RGB-percentage definitions and color-number mapping.\n- Repeat, carriage return, graphics next line, VT240 home, and safe indexed-pixel rasterization.\n\n## Deferred to later R03 slices\n\n- `AdaptDispatch` / `PageManager` integration.\n- `TextBuffer` / `ImageSlice` output.\n- Renderer redraw notifications.\n- Margin scrolling and viewport panning.\n- Partial-flush timing, packet-boundary, and palette-animation flush policy.\n- C++ facade / FFI integration.\n\nR03a intentionally replaces the raw-pointer rasterization algorithm with checked Rust indexing while preserving the observable Sixel raster semantics.\n""",
    encoding="utf-8",
)
